func (m taskRunMods) WithParentsCascading() TaskRunMod {
	return TaskRunModFunc(func(ctx context.Context, o *TaskRunTemplate) {
		if isDone, _ := taskRunWithParentsCascadingCtx.Value(ctx); isDone {
			return
		}
		ctx = taskRunWithParentsCascadingCtx.WithValue(ctx, true)
		{

			related := o.f.NewApprovalWithContext(ctx, ApprovalMods.WithParentsCascading())
			m.WithRunApproval(related).Apply(ctx, o)
		}
		{

			related := o.f.NewProjectWithContext(ctx, ProjectMods.WithParentsCascading())
			m.WithProject(related).Apply(ctx, o)
		}
		{

			related := o.f.NewUserWithContext(ctx, UserMods.WithParentsCascading())
			m.WithRequestedByUser(related).Apply(ctx, o)
		}
		{

			related := o.f.NewTaskTemplateWithContext(ctx, TaskTemplateMods.WithParentsCascading())
			m.WithTemplateTaskTemplate(related).Apply(ctx, o)
		}
	})
}

